<div class="section-heading"><div><div class="eyebrow">Plataforma</div><h1>Integrações Bancárias</h1><p class="text-secondary mb-0">Visão operacional das integrações dos clientes. Segredos nunca são exibidos ao Master.</p></div></div>
<div class="card"><div class="card-body"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Cliente</th><th>Provider</th><th>Ambiente</th><th>Status</th><th>Transações</th><th>Recebido</th><th>Último teste</th><th>Última sincronização</th></tr></thead><tbody><?php foreach($connections as $c):?><tr><td><?=htmlspecialchars($c['tenant_name'])?></td><td><?=htmlspecialchars($c['display_name'])?></td><td><?=htmlspecialchars($c['environment'])?></td><td><?=htmlspecialchars($c['status'])?></td><td><?=(int)$c['transaction_count']?></td><td>R$ <?=number_format((float)$c['paid_total'],2,',','.')?></td><td><?=$c['last_tested_at']?date('d/m/Y H:i',strtotime($c['last_tested_at'])):'—'?></td><td><?=$c['last_sync_at']?date('d/m/Y H:i',strtotime($c['last_sync_at'])):'—'?></td></tr><?php endforeach;?><?php if(!$connections):?><tr><td colspan="8" class="text-secondary">Nenhuma integração de cliente cadastrada.</td></tr><?php endif;?></tbody></table></div></div></div>
